gb1B(){return"Home"},
gb1A(){return"Away"},
gb1z(){return"Tension"},
gaP8(){return"Harmony"},
gaPi(){return"Analyse the harmony"},
gBP(){return"Inspect (tap a note)"},
gaP7(){return"Form"},
gaP3(){return"Circle of fifths"},
gaPg(){return"Tension"},
gafn(){return"Voice leading"},
gaPh(){return"No parallel 5ths or 8ves \u2713"},
gaPe(){return"Parallel fifths"},
gaPf(){return"Parallel octaves"},
gafm(){return"Non-chord tones"},
